f.write('<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Changa V35 V36 PWA</title><link rel="manifest" href="manifest.json"><meta name="theme-color" content="#facc15"><script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.39.7/dist/umd/supabase.min.js"></script><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-black text-white"><div class="max-w-lg mx-auto p-3"><div class="text-center py-3"><h1 class="text-3xl font-black">🔧 CHANGA APP 🇦🇷</h1><p id="loc" class="text-xs text-zinc-400">📍 Ezeiza - V35/V36 PWA - Radio 7km</p><div id="counts" class="grid grid-cols-3 gap-2 mt-3 bg-zinc-900 p-3 rounded-2xl text-sm font-bold">Cargando...</div><div class="flex gap-2 mt-3 overflow-x-auto pb-2" id="filtros"></div></div><div id="app"></div><div id="lista" class="mt-4 pb-24"></div></div><div id="installBar" class="fixed bottom-0 left-0 right-0 bg-yellow-400 text-black p-3 text-center font-black hidden"><button onclick="instalarPWA()">📲 INSTALAR CHANGA APP</button></div><script>\nconst SUPA_URL="https://tnfqcmbeonzicqoipjxm.supabase.co";const SUPA_KEY="sb_publishable_QiWOZ5m1Q1X3z1BxW0gi7Q_d6YXumnt";const db=supabase.createClient(SUPA_URL,SUPA_KEY);\nconst LOCS=["Ezeiza Centro","El Mirador","La Flecha","Sol de Oro","Canning","El Sosiego","Saint Thomas","La Union","Tristan Suarez","Spegazzini","Monte Grande","Luis Guillon","El Jaguel"];\nconst OFICIOS=["Todos","Albanil","Plomero","Electricista","Pintor","Carpintero","Herrero","Jardinero","Limpieza","Gasista","Techista","Cerrajero","Flete","Chofer"];\nlet coords={latitude:-34.8335,longitude:-58.4436},radio=7,filtroOficio="Todos",listaTrab=[],listaChangas=[],fotos={},deferredPrompt=null;\nfunction distKm(a,b,c,d){let R=6371;let dLa=(c-a)*Math.PI/180;let dLo=(d-b)*Math.PI/180;let e=Math.sin(dLa/2)**2+Math.cos(a*Math.PI/180)*Math.cos(c*Math.PI/180)*Math.sin(dLo/2)**2;return R*2*Math.atan2(Math.sqrt(e),Math.sqrt(1-e));}\nasync function uploadFoto(file,tipo){try{let nombre=tipo+"_"+Date.now()+"_"+file.name;let {data,error}=await db.storage.from("changa-fotos").upload(nombre,file);if(error) throw error;let {data:{publicUrl}}=db.storage.from("changa-fotos").getPublicUrl(nombre);return publicUrl;}catch(e){return new Promise(r=>{let fr=new FileReader();fr.onload=ev=>r(ev.target.result);fr.readAsDataURL(file);});}}\nfunction previewFoto(input,idPreview,key){let file=input.files[0];if(!file) return;fotos[key]=file;let r=new FileReader();r.onload=e=>{document.getElementById(idPreview).innerHTML="<img src="+e.target.result+" class=w-24 h-24 rounded-xl border-2 border-yellow-400>";};r.readAsDataURL(file);}\nfunction renderFiltros(){document.getElementById("filtros").innerHTML=OFICIOS.map(o=>"<button onclick=filtroOficio=\\""+o+"\\";renderLista() class=px-3 py-1 rounded-full text-xs font-bold whitespace-nowrap "+(filtroOficio==o?"bg-yellow-400 text-black":"bg-zinc-800")+">"+o+"</button>").join("");}\nfunction renderLista(){let html="<h3 class=font-black mb-2>📋 Changas a "+radio+"km</h3>";listaChangas.slice(0,10).forEach(x=>{let img=x.foto_changa?"<img src="+x.foto_changa+" class=w-full h-32 object-cover rounded-xl mb-2>":"";html+="<div class=bg-zinc-900 p-3 rounded-xl mb-2 border>"+img+"<b class=text-yellow-400>🔧 "+(x.descripcion||"")+"</b><br><a href=https://wa.me/"+(x.wsp||"")+" class=text-green-400>💬 WhatsApp</a></div>";});html+="<h3 class=font-black mt-4 mb-2>👷 Trabajadores "+filtroOficio+" a "+radio+"km</h3>";listaTrab.filter(x=>{if(filtroOficio!="Todos"&&!(x.oficio||"").includes(filtroOficio)) return false;return true;}).slice(0,20).forEach(x=>{let foto=x.foto_cara?"<img src="+x.foto_cara+" class=w-12 h-12 rounded-full inline-block mr-2>":"";html+="<div class=bg-white text-black p-3 rounded-xl mb-2>"+foto+"<b>"+(x.nombre||"")+"</b> - "+(x.oficio||"")+"<br><a href=https://wa.me/"+(x.wsp||"")+" class=text-green-600>💬 "+(x.wsp||"")+"</a></div>";});document.getElementById("lista").innerHTML=html;}\nfunction home(){document.getElementById("app").innerHTML="<div class=grid grid-cols-2 gap-3 mb-3><button onclick=cli() class=bg-blue-600 p-6 rounded-2xl font-black>👤 SOY CLIENTE</button><button onclick=trab() class=bg-yellow-400 text-black p-6 rounded-2xl font-black>🛠️ SOY TRABAJADOR</button></div><button onclick=pub() class=w-full bg-zinc-800 border border-yellow-400 p-4 rounded-2xl font-bold mb-4>+ PUBLICAR CHANGA CON FOTO 📸</button><div class=bg-zinc-900 rounded-2xl p-4 mb-4><p class=text-center text-yellow-400 font-bold mb-3>🎯 TU RADIO</p><div class=grid grid-cols-4 gap-2><button onclick=setR(5) class=p-3 rounded-xl "+(radio==5?"bg-yellow-400 text-black":"bg-white text-black")+">5km</button><button onclick=setR(7) class=p-3 rounded-xl "+(radio==7?"bg-yellow-400 text-black":"bg-white text-black")+">7km ⭐</button><button onclick=setR(10) class=p-3 rounded-xl "+(radio==10?"bg-yellow-400 text-black":"bg-white text-black")+">10km</button><button onclick=setR(20) class=p-3 rounded-xl "+(radio==20?"bg-yellow-400 text-black":"bg-white text-black")+">20km</button></div></div><div class=bg-white text-black rounded-2xl p-3><p class=font-black mb-2>📍 Mapa Google</p><iframe width=100% height=300 style=border-radius:12px;border:0 src=https://maps.google.com/maps?q="+coords.latitude+","+coords.longitude+"&z=14&output=embed></iframe><div class=grid grid-cols-2 gap-2 mt-3><button onclick=instalarPWA() class=bg-black text-white p-3 rounded-xl text-xs>📲 Instalar App</button><button onclick=activarNoti() class=bg-yellow-400 text-black p-3 rounded-xl text-xs>🔔 Avisos</button></div></div>";}\nfunction setR(r){radio=r;home();renderLista();}\nfunction cli(){document.getElementById("app").innerHTML="<div class=bg-white text-black rounded-[28px] p-6><h2 class=font-black mb-3>👤 CLIENTE</h2><input id=cn placeholder=Nombre class=w-full p-3 rounded-xl border mb-2><input id=cw placeholder=WhatsApp class=w-full p-3 rounded-xl border mb-2><button onclick=saveC() class=w-full bg-blue-600 text-white p-3 rounded-xl>GUARDAR</button><button onclick=home() class=w-full bg-zinc-100 p-3 rounded-xl mt-2>Cerrar</button></div>";}\nasync function saveC(){await db.from("clientes").insert([{nombre:document.getElementById("cn").value,wsp:document.getElementById("cw").value,lat:coords.latitude,lng:coords.longitude}]);alert("Guardado");home();load();}\nfunction trab(){document.getElementById("app").innerHTML="<div class=bg-white text-black rounded-[28px] p-5><h2 class=font-black mb-3>🛠️ TRABAJADOR V35</h2><label class=text-[10px] font-black>📸 FOTO CARA</label><input type=file accept=image/* onchange=previewFoto(this,pc,cara) class=w-full p-2 border rounded-xl mb-1><div id=pc class=mb-2></div><label class=text-[10px] font-black>🪪 FOTO DNI</label><input type=file accept=image/* onchange=previewFoto(this,pd,dni) class=w-full p-2 border rounded-xl mb-2><div id=pd class=mb-2></div><input id=tn placeholder=Nombre class=w-full p-3 rounded-xl border mb-2><input id=tw placeholder=WhatsApp class=w-full p-3 rounded-xl border mb-2><select id=to class=w-full p-3 rounded-xl border mb-2><option>Rubro</option><option>Albanil</option><option>Plomero</option><option>Electricista</option><option>Pintor</option></select><textarea id=tdesc placeholder=Sobre vos... class=w-full p-3 rounded-xl border mb-2></textarea><button onclick=saveT() id=btnT class=w-full bg-yellow-400 text-black p-4 rounded-xl>REGISTRARME CON FOTOS</button><button onclick=home() class=w-full bg-zinc-100 p-3 rounded-xl mt-2>Cerrar</button></div>";}\nasync function saveT(){let btn=document.getElementById("btnT");btn.innerText="⏳ Subiendo...";let urlCara="",urlDni="";if(fotos["cara"]) urlCara=await uploadFoto(fotos["cara"],"cara");if(fotos["dni"]) urlDni=await uploadFoto(fotos["dni"],"dni");await db.from("trabajadores").insert([{nombre:document.getElementById("tn").value,wsp:document.getElementById("tw").value,oficio:document.getElementById("to").value,descripcion:document.getElementById("tdesc").value,foto_cara:urlCara,foto_dni:urlDni,lat:coords.latitude,lng:coords.longitude,estrellas:"5.0"}]);alert("✅ Registrado con fotos!");home();load();}\nfunction pub(){document.getElementById("app").innerHTML="<div class=bg-white text-black rounded-[28px] p-5><h2 class=font-black mb-3>📸 CHANGA CON FOTO</h2><textarea id=chdesc placeholder=Que necesitas? class=w-full p-3 rounded-xl border mb-2 h-20></textarea><input type=file accept=image/* onchange=previewFoto(this,pch,changa) class=w-full p-2 border rounded-xl mb-2><div id=pch class=mb-2></div><input id=chw placeholder=WhatsApp class=w-full p-3 rounded-xl border mb-2><button onclick=saveCh() id=btnCh class=w-full bg-black text-white p-3 rounded-xl>PUBLICAR</button><button onclick=home() class=w-full bg-zinc-100 p-3 rounded-xl mt-2>Cerrar</button></div>";}\nasync function saveCh(){let urlCh="";if(fotos["changa"]) urlCh=await uploadFoto(fotos["changa"],"changa");await db.from("changas").insert([{descripcion:document.getElementById("chdesc").value,wsp:document.getElementById("chw").value,foto_changa:urlCh,lat:coords.latitude,lng:coords.longitude}]);alert("Publicada!");home();load();}\nasync function load(){try{let c=await db.from("clientes").select("*");let t=await db.from("trabajadores").select("*");let h=await db.from("changas").select("*");listaTrab=t.data||[];listaChangas=h.data||[];document.getElementById("counts").innerHTML="<div><b class=text-yellow-400 text-xl>"+(c.data?.length||0)+"</b><br>Clientes</div><div><b class=text-yellow-400 text-xl>"+(t.data?.length||0)+"</b><br>Trabajadores</div><div><b class=text-yellow-400 text-xl>"+(h.data?.length||0)+"</b><br>Changas</div>";renderFiltros();renderLista();}catch(e){renderFiltros();renderLista();}}\nfunction activarNoti(){Notification.requestPermission().then(p=>{if(p=="granted") alert("🔔 Notificaciones activadas!");});}\nwindow.addEventListener("beforeinstallprompt",e=>{e.preventDefault();deferredPrompt=e;document.getElementById("installBar").classList.remove("hidden");});\nfunction instalarPWA(){if(deferredPrompt){deferredPrompt.prompt();}else{alert("📲 3 puntitos -> Instalar app");}}\nif("serviceWorker" in navigator){navigator.serviceWorker.register("sw.js");}\nhome();load();\n</script></body></html>\n')
